// Generated by `spindle-storefront components types`; regenerate after changing components.
// Content as the Storefront API delivers it: text in the request locale, links with hrefs,
// products and categories as global ids (resolve them through Page.references).

export type BuilderImage = { url: string; alt: string | null; width: number | null; height: number | null };
export type BuilderLink = { kind: "url" | "page" | "product" | "category"; href: string | null; id: string | null; newTab: boolean };
export type BuilderItem<F> = { id: string; fields: F };
export type BuilderNode<C extends string, F, V extends string | null = null> = { id: string; component: C; variation: V; fields: F };

/** Button */
export type ButtonFields = {
  /** Label */
  label: string | null;
  /** Link */
  link: BuilderLink | null;
  /** Style */
  style: "primary" | "secondary" | "link" | null;
};
export type ButtonNode = BuilderNode<"button", ButtonFields, null>;

/** Category header: The category's name and description, with breadcrumbs. Shows category data, so only in category templates and sections. */
export type CategoryHeaderFields = {
  /** Banner image. Only for banner. */
  image?: BuilderImage | null;
  /** Show description */
  showDescription: boolean;
  /** Show breadcrumbs */
  showBreadcrumbs: boolean;
};
export type CategoryHeaderNode = BuilderNode<"category_header", CategoryHeaderFields, "simple" | "banner">;

/** Category page: A template for category pages: the category's products and any sections around them. A template for category pages. */
export type CategoryPageFields = {
  /** Sections */
  sections: Array<CategoryHeaderNode | SubcategoriesNode | CategoryProductsNode | CategorySectionsNode | HeroNode | RichTextNode | ProductGridNode | CategoryTilesNode | PromoBannerNode | ImageWithTextNode | FeatureListNode | TestimonialsNode | FaqNode | NewsletterNode | ColumnsNode | VideoNode | LogoCloudNode | SpacerNode>;
};
export type CategoryPageNode = BuilderNode<"category_page", CategoryPageFields, null>;

/** Category products: The category's products, with sorting and pages. Shows category data, so only in category templates and sections. */
export type CategoryProductsFields = {
  /** Products per page */
  pageSize: number | null;
  /** Columns */
  columns: "2" | "3" | "4" | null;
  /** Show sorting */
  showSort: boolean;
  /** Show prices */
  showPrices: boolean;
};
export type CategoryProductsNode = BuilderNode<"category_products", CategoryProductsFields, null>;

/** This category's sections: Where each category's own sections go. Categories without any show nothing here. Shows category data, so only in category templates and sections. */
export type CategorySectionsFields = Record<string, never>;
export type CategorySectionsNode = BuilderNode<"category_sections", CategorySectionsFields, null>;

/** Category sections: One category's own sections, shown where its template places them. Belongs to one category: render it where the category's template places its sections. */
export type CategorySectionsPageFields = {
  /** Sections */
  sections: Array<SubcategoriesNode | HeroNode | RichTextNode | ProductGridNode | CategoryTilesNode | PromoBannerNode | ImageWithTextNode | FeatureListNode | TestimonialsNode | FaqNode | NewsletterNode | ColumnsNode | VideoNode | LogoCloudNode | SpacerNode>;
};
export type CategorySectionsPageNode = BuilderNode<"category_sections_page", CategorySectionsPageFields, null>;

/** Category tiles: Image tiles linking to categories. */
export type CategoryTilesFields = {
  /** Title */
  title: string | null;
  /** Tiles */
  tiles: Array<BuilderItem<{ category: string | null; image: BuilderImage | null; label: string | null }>>;
};
export type CategoryTilesNode = BuilderNode<"category_tiles", CategoryTilesFields, null>;

/** Column */
export type ColumnFields = {
  /** Content */
  content: Array<TextBlockNode | ImageBlockNode | ButtonNode>;
};
export type ColumnNode = BuilderNode<"column", ColumnFields, null>;

/** Columns: Two to four columns of text, images and buttons. */
export type ColumnsFields = {
  /** Columns */
  columns: Array<ColumnNode>;
  /** Spacing */
  gap: "small" | "medium" | "large" | null;
};
export type ColumnsNode = BuilderNode<"columns", ColumnsFields, null>;

/** FAQ: Questions with expandable answers. */
export type FaqFields = {
  /** Title */
  title: string | null;
  /** Questions */
  items: Array<BuilderItem<{ question: string | null; answer: string | null }>>;
};
export type FaqNode = BuilderNode<"faq", FaqFields, null>;

/** Feature list: Icons with short benefits: shipping, returns, materials. */
export type FeatureListFields = {
  /** Title */
  title: string | null;
  /** Introduction */
  intro: string | null;
  /** Features */
  features: Array<BuilderItem<{ icon: "truck" | "refresh" | "shield" | "leaf" | "star" | "gift" | "heart" | "clock" | null; title: string | null; text: string | null }>>;
  /** Columns */
  columns: "2" | "3" | "4" | null;
};
export type FeatureListNode = BuilderNode<"feature_list", FeatureListFields, null>;

/** Footer column */
export type FooterColumnFields = {
  /** Title */
  title: string | null;
  /** Links */
  links: Array<BuilderItem<{ label: string | null; link: BuilderLink | null }>>;
};
export type FooterColumnNode = BuilderNode<"footer_column", FooterColumnFields, null>;

/** Hero: A large headline with an image and buttons. */
export type HeroFields = {
  /** Eyebrow */
  eyebrow: string | null;
  /** Title */
  title: string | null;
  /** Subtitle */
  subtitle: string | null;
  /** Image. Only for split, full_bleed. */
  image?: BuilderImage | null;
  /** Buttons */
  actions: Array<ButtonNode>;
  /** Theme */
  theme: "light" | "dark" | "brand" | null;
};
export type HeroNode = BuilderNode<"hero", HeroFields, "split" | "centered" | "full_bleed">;

/** Image */
export type ImageBlockFields = {
  /** Image */
  image: BuilderImage | null;
  /** Caption */
  caption: string | null;
  /** Link */
  link: BuilderLink | null;
};
export type ImageBlockNode = BuilderNode<"image_block", ImageBlockFields, null>;

/** Image with text */
export type ImageWithTextFields = {
  /** Image */
  image: BuilderImage | null;
  /** Title */
  title: string | null;
  /** Text */
  body: string | null;
  /** Buttons */
  actions: Array<ButtonNode>;
  /** Image position */
  imagePosition: "left" | "right" | null;
};
export type ImageWithTextNode = BuilderNode<"image_with_text", ImageWithTextFields, null>;

/** Landing page: A page assembled from sections: home, campaigns, brand stories. */
export type LandingPageFields = {
  /** Sections */
  sections: Array<HeroNode | RichTextNode | ProductGridNode | CategoryTilesNode | PromoBannerNode | ImageWithTextNode | FeatureListNode | TestimonialsNode | FaqNode | NewsletterNode | ColumnsNode | VideoNode | LogoCloudNode | SpacerNode>;
};
export type LandingPageNode = BuilderNode<"landing_page", LandingPageFields, null>;

/** Logo cloud */
export type LogoCloudFields = {
  /** Title */
  title: string | null;
  /** Logos */
  logos: Array<BuilderItem<{ image: BuilderImage | null; name: string | null; link: BuilderLink | null }>>;
};
export type LogoCloudNode = BuilderNode<"logo_cloud", LogoCloudFields, null>;

/** Newsletter sign-up */
export type NewsletterFields = {
  /** Title */
  title: string | null;
  /** Text */
  text: string | null;
  /** Button label */
  buttonLabel: string | null;
  /** Consent note */
  consent: string | null;
};
export type NewsletterNode = BuilderNode<"newsletter", NewsletterFields, null>;

/** Product description: The product's description from the catalog. Shows product data, so only in product templates and sections. */
export type ProductDescriptionFields = {
  /** Title */
  title: string | null;
};
export type ProductDescriptionNode = BuilderNode<"product_description", ProductDescriptionFields, null>;

/** Product details: The product's gallery, name, price, options and add to cart button. Shows product data, so only in product templates and sections. */
export type ProductDetailsFields = {
  /** Purchase note. A line under the add to cart button. */
  note: string | null;
  /** Show breadcrumbs */
  showBreadcrumbs: boolean;
};
export type ProductDetailsNode = BuilderNode<"product_details", ProductDetailsFields, "gallery_left" | "gallery_right">;

/** Product grid: Products picked by hand, from a category, or the newest arrivals. */
export type ProductGridFields = {
  /** Title */
  title: string | null;
  /** Products from */
  source: "manual" | "category" | "newest" | null;
  /** Products. Used when products are picked by hand. */
  products: string[];
  /** Category. Used when products come from a category, in its Featured order. */
  category: string | null;
  /** How many */
  limit: number | null;
  /** Columns. Only for grid. */
  columns?: "2" | "3" | "4" | null;
  /** Show prices */
  showPrices: boolean;
  /** “View all” link */
  link: BuilderLink | null;
};
export type ProductGridNode = BuilderNode<"product_grid", ProductGridFields, "grid" | "carousel">;

/** Product page: A template for product pages: the product's details and any sections around them. A template for product pages. */
export type ProductPageFields = {
  /** Sections */
  sections: Array<ProductDetailsNode | ProductDescriptionNode | ProductSpecsNode | RelatedProductsNode | ProductSectionsNode | HeroNode | RichTextNode | ProductGridNode | CategoryTilesNode | PromoBannerNode | ImageWithTextNode | FeatureListNode | TestimonialsNode | FaqNode | NewsletterNode | ColumnsNode | VideoNode | LogoCloudNode | SpacerNode>;
};
export type ProductPageNode = BuilderNode<"product_page", ProductPageFields, null>;

/** This product's sections: Where each product's own sections go. Products without any show nothing here. Shows product data, so only in product templates and sections. */
export type ProductSectionsFields = Record<string, never>;
export type ProductSectionsNode = BuilderNode<"product_sections", ProductSectionsFields, null>;

/** Product sections: One product's own sections, shown where its template places them. Belongs to one product: render it where the product's template places its sections. */
export type ProductSectionsPageFields = {
  /** Sections */
  sections: Array<ProductDescriptionNode | ProductSpecsNode | RelatedProductsNode | HeroNode | RichTextNode | ProductGridNode | CategoryTilesNode | PromoBannerNode | ImageWithTextNode | FeatureListNode | TestimonialsNode | FaqNode | NewsletterNode | ColumnsNode | VideoNode | LogoCloudNode | SpacerNode>;
};
export type ProductSectionsPageNode = BuilderNode<"product_sections_page", ProductSectionsPageFields, null>;

/** Product specifications: The product's attributes as a table: material, fit, care. Shows product data, so only in product templates and sections. */
export type ProductSpecsFields = {
  /** Title */
  title: string | null;
};
export type ProductSpecsNode = BuilderNode<"product_specs", ProductSpecsFields, null>;

/** Promo banner: A slim announcement, e.g. a discount code. Schedule it with visibility dates. */
export type PromoBannerFields = {
  /** Text */
  text: string | null;
  /** Discount code */
  code: string | null;
  /** Link */
  link: BuilderLink | null;
  /** Tone */
  tone: "sale" | "info" | "dark" | null;
};
export type PromoBannerNode = BuilderNode<"promo_banner", PromoBannerFields, null>;

/** Related products: More products from the product's category, or the newest arrivals. Shows product data, so only in product templates and sections. */
export type RelatedProductsFields = {
  /** Title */
  title: string | null;
  /** Products from */
  source: "category" | "newest" | null;
  /** How many */
  limit: number | null;
  /** Show prices */
  showPrices: boolean;
};
export type RelatedProductsNode = BuilderNode<"related_products", RelatedProductsFields, null>;

/** Rich text: Formatted text: headings, paragraphs, lists and links (Markdown). */
export type RichTextFields = {
  /** Content */
  content: string | null;
  /** Width */
  width: "narrow" | "normal" | "wide" | null;
  /** Alignment */
  align: "left" | "center" | null;
};
export type RichTextNode = BuilderNode<"rich_text", RichTextFields, null>;

/** Site footer */
export type SiteFooterFields = {
  /** Link columns */
  columns: Array<FooterColumnNode>;
  /** Tagline */
  tagline: string | null;
  /** Legal line */
  legal: string | null;
};
export type SiteFooterNode = BuilderNode<"site_footer", SiteFooterFields, null>;

/** Site header: The announcement bar and main navigation on every page. */
export type SiteHeaderFields = {
  /** Announcement. A short line above the navigation; empty hides the bar. */
  announcement: string | null;
  /** Announcement link */
  announcementLink: BuilderLink | null;
  /** Navigation */
  navigation: Array<BuilderItem<{ label: string | null; link: BuilderLink | null; highlight: boolean }>>;
};
export type SiteHeaderNode = BuilderNode<"site_header", SiteHeaderFields, null>;

/** Spacer */
export type SpacerFields = {
  /** Size */
  size: "small" | "medium" | "large" | null;
  /** Show a line */
  divider: boolean;
};
export type SpacerNode = BuilderNode<"spacer", SpacerFields, null>;

/** Subcategories: Links to the category's subcategories; nothing shows where there are none. Shows category data, so only in category templates and sections. */
export type SubcategoriesFields = {
  /** Title */
  title: string | null;
};
export type SubcategoriesNode = BuilderNode<"subcategories", SubcategoriesFields, "pills" | "cards">;

/** Testimonials */
export type TestimonialsFields = {
  /** Title */
  title: string | null;
  /** Quotes */
  quotes: Array<BuilderItem<{ quote: string | null; author: string | null; role: string | null; avatar: BuilderImage | null }>>;
};
export type TestimonialsNode = BuilderNode<"testimonials", TestimonialsFields, null>;

/** Text */
export type TextBlockFields = {
  /** Content */
  content: string | null;
};
export type TextBlockNode = BuilderNode<"text_block", TextBlockFields, null>;

/** Video */
export type VideoFields = {
  /** Video URL. An MP4 file or a YouTube/Vimeo link. */
  url: string | null;
  /** Poster image */
  poster: BuilderImage | null;
  /** Caption */
  caption: string | null;
  /** Autoplay muted */
  autoplay: boolean;
};
export type VideoNode = BuilderNode<"video", VideoFields, null>;

/** Any component that can appear inside a blocks field. */
export type BuilderComponentNode = ProductDetailsNode | ProductDescriptionNode | ProductSpecsNode | RelatedProductsNode | CategoryHeaderNode | SubcategoriesNode | CategoryProductsNode | ProductSectionsNode | CategorySectionsNode | HeroNode | RichTextNode | ProductGridNode | CategoryTilesNode | PromoBannerNode | ImageWithTextNode | FeatureListNode | TestimonialsNode | FaqNode | NewsletterNode | ColumnsNode | ColumnNode | VideoNode | LogoCloudNode | SpacerNode | ButtonNode | TextBlockNode | ImageBlockNode | FooterColumnNode;
/** The root of a page, by content type. */
export type BuilderContentTypeNode = LandingPageNode | SiteHeaderNode | SiteFooterNode | ProductPageNode | CategoryPageNode | ProductSectionsPageNode | CategorySectionsPageNode;
export type BuilderComponentCode = BuilderComponentNode["component"];
export type BuilderContentTypeCode = BuilderContentTypeNode["component"];

/** Components that show product data: they render inside product templates and a product's own sections, with the product. */
export type BuilderProductComponentCode = "product_details" | "product_description" | "product_specs" | "related_products" | "product_sections";
/** Components that show category data: they render inside category templates and a category's own sections, with the category. */
export type BuilderCategoryComponentCode = "category_header" | "subcategories" | "category_products" | "category_sections";
